sp_widget.client_script:
api.controller = function($window) {
    var c = this;

    function pad(n) {
        return ('0' + n).slice(-2);
    }

    function fmt(d) {
        return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
    }

    var today = new Date();
    today.setHours(0, 0, 0, 0);

    c.today = fmt(today);
    c.guests = "2";
    c.roomType = "Any";
    c.error = '';

    c.minCheckout = function() {
        return c.checkin ? fmt(new Date(c.checkin)) : c.today;
    };

    c.searchRooms = function() {
        c.error = '';

        if (!c.checkin || !c.checkout) {
            c.error = 'Please choose your check-in and check-out dates.';
            return;
        }

        var ci = new Date(c.checkin);
        var co = new Date(c.checkout);

        ci.setHours(0, 0, 0, 0);
        co.setHours(0, 0, 0, 0);

        if (ci < today) {
            c.error = 'Check-in date cannot be in the past.';
            return;
        }

        if (co <= ci) {
            c.error = 'Check-out must be later than check-in.';
            return;
        }

        var url = '?id=book_room' +
            '&checkin=' + fmt(ci) +
            '&checkout=' + fmt(co) +
            '&guests=' + encodeURIComponent(c.guests);

        if (c.roomType && c.roomType !== 'Any') {
            url += '&room_type=' + encodeURIComponent(c.roomType);
        }

        $window.location.href = url;
    };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');

.ch-search-wrap {
  margin-top: -62px;
  position: relative;
  z-index: 5;
  width: 100%;
}

.ch-search-container {
  width: 92%;
  max-width: 1120px;
  margin: 0 auto;
}

.ch-search-bar {
  background: #1f3a30;
  border-radius: 6px;
  padding: 18px 22px;
  display: grid;
  grid-template-columns: repeat(4, 1fr) auto;
  gap: 18px;
  align-items: center;
  box-shadow: 0 18px 40px rgba(22, 42, 34, .3);
  margin: 0;
  border: none;
  font-family: 'Inter', system-ui, sans-serif;
  box-sizing: border-box;
}

.ch-search-bar *,
.ch-search-bar *::before,
.ch-search-bar *::after {
  box-sizing: border-box;
}

.ch-search-field {
  min-width: 0;
}

.ch-search-field label {
  display: block;
  color: #e6c79c;
  font-size: .62rem;
  letter-spacing: .18em;
  text-transform: uppercase;
  margin-bottom: 4px;
  font-family: 'Inter', system-ui, sans-serif;
  font-weight: 400;
}

.ch-search-field input,
.ch-search-field select {
  width: 100%;
  height: auto;
  background: transparent;
  border: none;
  border-bottom: 1px solid rgba(255, 255, 255, .25);
  border-radius: 0;
  box-shadow: none;
  color: #ffffff;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: .9rem;
  padding: 4px 0;
  outline: none;
  margin: 0;
}

.ch-search-field input:focus,
.ch-search-field select:focus {
  border-bottom-color: rgba(255, 255, 255, .6);
  box-shadow: none;
  outline: none;
}

.ch-search-field select option {
  color: #2a2d29;
  background: #ffffff;
}

.ch-search-btn {
  display: inline-block;
  padding: 12px 26px;
  border-radius: 6px;
  font-size: .78rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  border: 1px solid transparent;
  cursor: pointer;
  transition: .25s ease;
  font-family: 'Inter', system-ui, sans-serif;
  background: #e6c79c;
  color: #1f3a30;
  white-space: nowrap;
  margin: 0;
}

.ch-search-btn:hover {
  background: #d4b07c;
  color: #1f3a30;
  transform: translateY(-2px);
}

.ch-search-error {
  margin-top: 12px;
  padding: 10px 14px;
  background: #f8e4e0;
  border: 1px solid #b4483a;
  border-radius: 6px;
  color: #8a3a2f;
  font-size: .86rem;
}

@media (max-width: 900px) {
  .ch-search-bar {
    grid-template-columns: 1fr;
  }

  .ch-search-btn {
    width: 100%;
  }
}
